def rect(x,y,w,h,c,rx=0):return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{rx}" fill="{c}"/>'
def circle(x,y,r,c):return f'<circle cx="{x}" cy="{y}" r="{r}" fill="{c}"/>'
def path(d,c,stroke='none',width=1):return f'<path d="{d}" fill="{c}" stroke="{stroke}" stroke-width="{width}" stroke-linecap="round" stroke-linejoin="round"/>'
def person(x,y,shirt='#39796c',scale=1):
 s=circle(0,-48,14,'#bd835d')+path('M-14 -50 Q-16 -67 0 -66 Q16 -66 14 -47 L8 -53 L-12 -53Z','#382f30')+rect(-19,-31,38,43,10 if False else shirt,10)+path('M-9 9 L-11 34 M10 9 L12 34','none','#304f63',8)+path('M-19 -23 L-29 -3 M19 -23 L28 -4','none','#bd835d',7)
 return f'<g transform="translate({x} {y}) scale({scale})">{s}</g>'
def tree(x,y):return f'<g transform="translate({x} {y})">'+rect(-6,-30,12,55,'#8c6547',4)+circle(-18,-42,24,'#6d9774')+circle(17,-44,24,'#497e64')+circle(0,-65,24,'#8ab18b')+'</g>'
def book(x,y,c):return rect(x,y,24,36,c,3)+rect(x+4,y+5,16,2,'#f8e4bd')+rect(x+4,y+10,12,2,'#f8e4bd')
def shelf(x,y):return rect(x,y,112,128,'#895f49',5)+rect(x+8,y+8,96,52,'#e5cfab')+rect(x+8,y+68,96,52,'#e5cfab')+''.join(book(x+12+i*26,y+20,c) for i,c in enumerate(['#5c8b80','#b97651','#627d9c']))+''.join(book(x+12+i*26,y+80,c) for i,c in enumerate(['#a69150','#7a6490','#39796c']))
